```jsx
// BEFORE: this combination is duplicated in every component that fetches something
function UserProfile({ userId }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetch(`/api/users/${userId}`)
      .then((res) => res.json())
      .then((json) => setData(json))
      .catch((err) => setError(err))
      .finally(() => setLoading(false));
  }, [userId]);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong.</p>;
  return <p>{data.name}</p>;
}

// AFTER: the pattern is extracted once and reused
function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetch(url)
      .then((res) => res.json())
      .then((json) => setData(json))
      .catch((err) => setError(err))
      .finally(() => setLoading(false));
  }, [url]);

  return { data, loading, error };
}

function UserProfile({ userId }) {
  const { data, loading, error } = useFetch(`/api/users/${userId}`);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong.</p>;
  return <p>{data.name}</p>;
}
```

useFetch is a function that calls useState three times and useEffect once, bundled behind one name and one return shape. UserProfile, and any component with the same need, can now call `useFetch(url)`. Those hook calls still belong to whichever component calls useFetch on a given render. React doesn't care that they're written inside a different function; what matters is that useFetch is called unconditionally, at the top level, on every render of its caller. This version is deliberately minimal: it has no guard against a slow, stale response overwriting a newer one (see the effect lesson's `isCurrent` flag), and it doesn't check `res.ok`, because `fetch` only rejects on network failure, so a 404 would reach `.json()` and be treated as data.

