const UserContext = createContext(null);
const ThemeContext = createContext(null);

function App() {
  const [user, setUser] = useState({ name: "Amara" });
  const [theme, setTheme] = useState("light");

  const userValue = useMemo(() => ({ user, setUser }), [user]);
  const themeValue = useMemo(() => ({ theme, setTheme }), [theme]);

  return (
    <UserContext.Provider value={userValue}>
      <ThemeContext.Provider value={themeValue}>
        <ThemeLabel />
        <UserGreeting />
        <ToggleThemeButton />
      </ThemeContext.Provider>
    </UserContext.Provider>
  );
}

const ThemeLabel = memo(function ThemeLabel() {
  const { theme } = useContext(ThemeContext);
  console.log("ThemeLabel rendered");
  return <span>{theme}</span>;
});

const UserGreeting = memo(function UserGreeting() {
  const { user } = useContext(UserContext);
  console.log("UserGreeting rendered");
  return <span>Hi, {user.name}</span>;
});

function ToggleThemeButton() {
  const { theme, setTheme } = useContext(ThemeContext);
  return (
    <button onClick={() => setTheme(theme === "light" ? "dark" : "light")}>
      Toggle theme
    </button>
  );
}

